-- ============================================================
-- SEED EXT 3: Módulo 14 — Passive Voice (ex 201-260)
-- Novos tópicos: get-passive, duplo objeto passivo, passivo
-- modal + perfeito, gerúndio e infinitivo passivos, TOEFL
-- ============================================================
DO $$
DECLARE cid TEXT;
BEGIN
  SELECT id INTO cid FROM contents WHERE id = 'passive-voice';
  IF cid IS NULL THEN RAISE EXCEPTION 'Módulo passive-voice não encontrado'; END IF;

  INSERT INTO exercises (content_id, block_number, exercise_number, type, question, answer, options, explanation, difficulty) VALUES

  -- BLOCK 31: get-passive (informal / resultado)
  (cid,31,201,'gap_fill','He _____ (get/fire) after the company discovered the accounting irregularities.','got fired',NULL,'"Get + past participle" = get-passive. Emphasizes result, often unexpected or unfortunate.','medium'),
  (cid,31,202,'multiple_choice','What is the difference between "was fired" and "got fired"?','"Was fired" is neutral; "got fired" is more informal and emphasizes the result (often negative).','["They are identical in all contexts","''Was fired'' is more informal","''Was fired'' is neutral; ''got fired'' is more informal and emphasizes the result (often negative).","Get-passive is always wrong in standard English"]','"Be-passive" = neutral description. "Get-passive" = result-focused, informal, often undesirable outcome.','hard'),
  (cid,31,203,'gap_fill','Several students _____ (get/fail) because they submitted plagiarized work.','got failed / got caught / were failed',NULL,'"Got failed/caught" = get-passive for undesirable results with personal subject.','medium'),
  (cid,31,204,'multiple_choice','Which sentence uses get-passive MOST naturally?','She got promoted after three years of outstanding performance reviews.','["The paper got published in Nature (informal but acceptable).","The experiment got conducted under strict conditions (wrong — ''conduct'' is a formal process, not a personal result).","She got promoted after three years of outstanding performance reviews.","The data got analyzed by the research team (wrong register)."]','"Got promoted" = natural get-passive for a personal career event.','medium'),
  (cid,31,205,'gap_fill','The building _____ (get/damage) severely during the storm last week.','got damaged',NULL,'"Got damaged" = get-passive for unintended physical result.','easy'),

  -- BLOCK 32: duplo objeto passivo (was given / was told / was awarded)
  (cid,32,206,'gap_fill','All participants _____ (give/passive) written instructions before the experiment began.','were given',NULL,'"Were given" = passive of ditransitive verb. The indirect object becomes the passive subject.','medium'),
  (cid,32,207,'multiple_choice','Which passive transformation is CORRECT for "The committee awarded her the prize"?','Both "She was awarded the prize" and "The prize was awarded to her" are correct.','["She was awarded to the prize by the committee.","Only ''The prize was awarded to her'' is correct (active object passive).","Both ''She was awarded the prize'' and ''The prize was awarded to her'' are correct.","Only ''She was awarded the prize'' is correct."]','Ditransitive verbs (award, give, send, show, tell) allow TWO passive forms.','hard'),
  (cid,32,208,'gap_fill','Attendees _____ (show/passive) a preliminary version of the results at the conference.','were shown',NULL,'"Were shown" = passive with indirect object as subject (show + IO + DO).','medium'),
  (cid,32,209,'multiple_choice','Which sentence uses a double-object passive INCORRECTLY?','Students were given to a copy of the syllabus on the first day.','["Students were given a copy of the syllabus on the first day (correct).","A copy of the syllabus was given to students on the first day (correct).","Students were taught the correct procedure in the training session (correct).","Students were given to a copy of the syllabus on the first day."]','"Were given to a copy" = error. "Were given a copy" (IO passive) or "A copy was given to students" (DO passive).','hard'),
  (cid,32,210,'gap_fill','The winning team _____ (tell/passive) that their proposal _____ (select/passive) over forty competing entries.','were told / had been selected',NULL,'Double object passive + past perfect passive for prior selection.','hard'),

  -- BLOCK 33: modal + passivo (must be, should be, may be, can be)
  (cid,33,211,'gap_fill','These guidelines _____ (must + follow/passive) by all research staff without exception.','must be followed',NULL,'"Must be + past participle" = strong obligation + passive.','medium'),
  (cid,33,212,'multiple_choice','Which modal passive correctly expresses a recommendation in academic writing?','The findings should be interpreted in light of the study''s methodological limitations.','["The findings must interpreted in light of the limitations.","The findings should be interpretating in light of the limitations.","The findings should be interpreted in light of the study''s methodological limitations.","The findings should have interpret in light of the limitations."]','"Should be + past participle" = passive recommendation.','medium'),
  (cid,33,213,'gap_fill','Causation _____ (cannot/establish/passive) from correlational data alone.','cannot be established',NULL,'"Cannot be + past participle" = negative obligation/impossibility + passive.','hard'),
  (cid,33,214,'multiple_choice','Which sentence uses modal passive correctly for possibility in academic writing?','This discrepancy may be attributed to measurement error or sampling bias.','["This discrepancy may attributed to measurement error.","This discrepancy may be attributing to measurement error.","This discrepancy may be attributed to measurement error or sampling bias.","This discrepancy might have attribute to measurement error."]','"May be + past participle" = possibility + passive (academic hedging).','medium'),
  (cid,33,215,'gap_fill','The data _____ (might/misinterpret/passive) if contextual factors _____ (not/take/passive) into account.','might be misinterpreted / are not taken',NULL,'Modal passive + conditional passive in academic risk statement.','hard'),

  -- BLOCK 34: passivo perfeito (have been + PP) em contexto acadêmico
  (cid,34,216,'gap_fill','Multiple approaches _____ (propose/passive) to address this gap, but none _____ (validate/passive) empirically.','have been proposed / has been validated',NULL,'Present perfect passive for recent proposals and lack of validation.','hard'),
  (cid,34,217,'multiple_choice','Which sentence uses present perfect passive CORRECTLY in an academic literature review?','The relationship between stress and immune function has been studied extensively over the past three decades.','["The relationship between stress and immune function was studied extensively (PS — acceptable but less linking to present)","The relationship has studied extensively.","The relationship between stress and immune function has been studied extensively over the past three decades.","The relationship between stress and immune function is studied extensively."]','"Has been studied" = present perfect passive = connects past research to present relevance.','medium'),
  (cid,34,218,'gap_fill','The methodology _____ (criticize/passive) in several peer reviews, leading the authors to revise the original approach.','has been criticized / was criticized',NULL,'Passive perfect or passive past for prior methodological critique.','medium'),
  (cid,34,219,'multiple_choice','Which tense-passive combination describes an action completed before a past event?','The report had been submitted before the deadline was announced.','["The report has been submitted before the deadline (present perfect — wrong tense for before past).","The report is submitted before the deadline.","The report had been submitted before the deadline was announced.","The report was being submitted before the deadline."]','"Had been + past participle" = past perfect passive for action prior to another past event.','hard'),

  -- BLOCK 35: infinitivo e gerúndio passivos
  (cid,35,220,'gap_fill','The proposal _____ (expect/passive/infinitive) to _____ (approve/passive) by the board within the next month.','is expected / be approved',NULL,'"Is expected to be approved" = passive infinitive: to + be + past participle.','hard'),
  (cid,35,221,'multiple_choice','Which sentence uses a PASSIVE INFINITIVE correctly?','The research is considered to be groundbreaking by experts in the field.','["The research considers to be groundbreaking.","The research is considered being groundbreaking.","The research is considered to be groundbreaking by experts in the field.","The research is considered to have being groundbreaking."]','"Is considered to be" = passive + passive infinitive construction.','hard'),
  (cid,35,222,'gap_fill','The author objected to _____ (edit/passive) without prior consultation.','being edited',NULL,'"Object to + being + past participle" = gerund passive.','hard'),
  (cid,35,223,'multiple_choice','Which sentence uses a PASSIVE GERUND correctly?','The participant''s anonymity was ensured by the data being encrypted before storage.','["The participant''s anonymity was ensured by the data encrypting before storage.","The participant''s anonymity was ensured by the data being encrypted before storage.","The participant''s anonymity was ensured by the data to be encrypted before storage.","The participant''s anonymity was ensured by encrypting the data before storage (active gerund — also correct)."]','"Data being encrypted" = passive gerund (the data is the patient of the encrypting action).','hard'),

  -- BLOCK 36: TOEFL Reading
  (cid,36,224,'multiple_choice','[TOEFL Reading] "Participants were randomly assigned to one of three experimental conditions." This passive construction:','Focuses on the process rather than who performed the randomization.','["Is incorrect — active voice is preferred","Focuses on the process rather than who performed the randomization.","Is used because the researchers are unknown","Emphasizes the researchers over the process"]','Passive = agent de-emphasized. Common in methods sections.','easy'),
  (cid,36,225,'gap_fill','[TOEFL Reading] "This phenomenon has _____ (study/passive) extensively in Western contexts but has received little attention in non-Western settings." Best form?','been studied',NULL,'"Has been studied" = present perfect passive for ongoing research relevance.','easy'),
  (cid,36,226,'multiple_choice','[TOEFL Reading] "The anomaly may be explained by a previously undiscovered subsurface mineral deposit." "May be explained" is a:','Hedged passive possibility — the cause is uncertain.','["Definitive passive cause","Hedged passive possibility — the cause is uncertain.","Obligation expressed passively","A passive gerund"]','"May be + past participle" = uncertain possibility, passive voice.','easy'),
  (cid,36,227,'gap_fill','[TOEFL Reading] "The participants _____ (tell/passive) that their identity would remain confidential." Best form?','were told',NULL,'"Were told" = double object passive (IO as subject: the committee told the participants).','medium'),

  -- BLOCK 37: TOEFL Speaking
  (cid,37,228,'production','[TOEFL Speaking — 45s] A reading discusses how social media companies should be regulated. Use: modal passive (must be, should be, may be, cannot be), passive infinitive (is expected to be), get-passive, and be-passive.','',NULL,'Social media companies must be held accountable for the content that spreads on their platforms. Algorithmic transparency should be mandated by law, and independent audits ought to be conducted annually. Harmful content cannot be effectively moderated without significant investment in human review teams working alongside automated systems. Companies are expected to be given clear legal obligations within the next legislative cycle; those that fail to comply should get penalized with substantial fines. Critics rightly argue that self-regulation has been tried and has demonstrably failed — binding regulation must now be implemented.','hard'),
  (cid,37,229,'production','[TOEFL Speaking — 45s] Discuss what should be done to address ocean plastic pollution. Use passive voice throughout: past passive (what was done), present passive (what is being done), modal passive (must/should/may be done), perfect passive (has been done), passive infinitive.','',NULL,'Awareness of ocean plastic pollution was raised significantly through viral media campaigns in the 2010s. Since then, international agreements have been signed, and some rivers — previously identified as major conduits of plastic waste — have been partially cleaned. Currently, biodegradable packaging is being developed by materials scientists, and several nations'' coastal cleanup programs are being expanded. However, far more must be done at the source. Single-use plastics need to be banned globally, and extended producer responsibility legislation should be passed to make manufacturers financially liable for end-of-life plastic disposal. Plastic production itself is expected to be capped under proposed UN treaty frameworks.','hard'),

  -- BLOCK 38: TOEFL Writing
  (cid,38,230,'production','[TOEFL Writing — 150 words] Write an academic paragraph on "The passive voice in scientific research reports." Use: present passive (×2), past passive (×2), modal passive (×2), perfect passive (×1), passive infinitive (×1), passive gerund (×1).','',NULL,'The passive voice is used extensively in scientific research reports because it emphasizes processes and results rather than the researchers themselves. Data are typically collected using standardized instruments that have been validated in prior studies. In methods sections, procedures are described in the past passive — samples were prepared, measurements were taken, and results were recorded — to convey a sense of objectivity and replicability. Findings must be presented with appropriate statistical context, and claims of causation should be supported by experimental rather than merely correlational evidence. The passive is also preferred when the agent is unknown, irrelevant, or better left implicit: "errors were detected" does not require naming who detected them. Being written in the passive voice, research reports signal institutional authority and scientific convention; this grammatical choice is expected to be made deliberately rather than by default.','hard'),
  (cid,38,231,'production','[TOEFL Writing — Error Correction] Fix passive voice errors: "The samples collected manually. Several approaches have been propose to address this gap. The participants were giving detailed instructions. The data might misinterpret without context. The proposal is expected approve by next month."','',NULL,'The samples collected → The samples were collected (missing ''were'' for past passive); have been propose → have been proposed (past participle required: propose → proposed); were giving detailed instructions → were given detailed instructions (double object passive: give + IO as subject → were given); might misinterpret → might be misinterpreted (modal passive: might be + past participle); expected approve → expected to be approved (passive infinitive: is expected + to be + past participle).','hard')

  ON CONFLICT (content_id, block_number, exercise_number) DO NOTHING;
END $$;
